import workcell,re,sys

def call(*a):
 r=workcell.call(*a);print(' '.join(map(str,a)),r.text,flush=True)
 if not r.ok: raise RuntimeError(r.text)
 return r

def loc():
 t=call('vision','locate').text
 p=re.search(r'lower end x=([-\d.]+) y=([-\d.]+) z=([-\d.]+)',t)
 if not p: raise RuntimeError('no peg endpoint')
 return tuple(map(float,p.groups()))

def step(dx,dy,dz):return call('robot','step','right',round(dx,1),round(dy,1),round(dz,1))

def align(maxmove=8):
 x,y,z=loc();dx=max(-maxmove,min(maxmove,-x));dy=max(-maxmove,min(maxmove,60-y));
 if abs(dx)>0.5 or abs(dy)>0.5:step(dx,dy,0)
 return loc()

for i in range(2):
 print('====== RUN',i+2,'======',flush=True)
 call('trial','start')
 call('robot','pick','cap','--arm','left')
 call('robot','place','bin','--arm','left')
 call('robot','pick','peg','--arm','right')
 call('robot','move','right',0,60,130)
 align()
 step(0,0,-12)
 align(5)
 step(0,0,-10)
 x,y,z=loc()
 if z>49:raise RuntimeError('peg did not enter hole at first push')
 step(0,0,-20)
 x,y,z=loc()
 if z>30:raise RuntimeError('peg did not descend into hole')
 step(0,0,-8)
 x,y,z=loc()
 if z>18:raise RuntimeError('peg not seated')
 call('robot','grip','right','open')
 call('robot','move','right',180,0,300)
 call('trial','end')
